import { Mesh, OctahedronGeometry, PlaneGeometry, BufferGeometry, BufferAttribute, DirectionalLight, Color, Group } from 'three/webgpu';
import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const group = new Group();

  // 1. TRIANGULAR PRISM GEOMETRY
  const prismGeometry = createTriangularPrism(1.2, 1.8);

  // 2. PRISM MATERIAL: Glass with dispersion via iridescence
  const prismMaterial = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    side: THREE.DoubleSide,
    attenuationColor: new Color('#e8ecf2'),
    attenuationDistance: 2.5,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    toneMapped: true,
  });

  const prismMesh = new Mesh(prismGeometry, prismMaterial);
  prismMesh.rotation.z = THREE.MathUtils.degToRad(12);
  prismMesh.rotation.y = THREE.MathUtils.degToRad(20);
  group.add(prismMesh);

  // 3. EMISSIVE CORE (octahedron inside prism)
  const coreGeometry = new OctahedronGeometry(0.35);
  const coreMaterial = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 2.2,
    metalness: 0,
    roughness: 1,
  });
  const coreMesh = new Mesh(coreGeometry, coreMaterial);
  group.add(coreMesh);

  // 4. BACK RIM LIGHT (cool directional from behind-left)
  const rimLight = new DirectionalLight(0x9fb0c4, 1.0);
  rimLight.position.set(-2.5, 1.5, 2.0);
  rimLight.target.position.set(0, 0, 0);
  group.add(rimLight);
  group.add(rimLight.target);

  // 5. CAUSTIC STREAK PLANE with TSL gradient
  const causticGeometry = new PlaneGeometry(2.4, 0.5);

  // TSL-based color gradient: #ff2a38 → #e8ecf2 → #9fb0c4
  const u = uv().x;
  const color1 = vec3(1.0, 0.165, 0.22);      // #ff2a38
  const color2 = vec3(0.91, 0.925, 0.949);    // #e8ecf2
  const color3 = vec3(0.624, 0.69, 0.769);    // #9fb0c4

  const gradientNode = mix(
    mix(color1, color2, smoothstep(0.2, 0.5, u)),
    color3,
    smoothstep(0.5, 0.8, u)
  );

  const causticMaterial = new MeshBasicNodeMaterial({
    colorNode: gradientNode,
    transparent: true,
    opacity: 0.35,
    side: THREE.DoubleSide,
  });

  const causticMesh = new Mesh(causticGeometry, causticMaterial);
  causticMesh.position.y = -1.1;
  causticMesh.position.z = -0.1;
  group.add(causticMesh);

  // 6. TEXT CONTENT
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Parse by role
  const textByRole = {};
  for (const item of textItems) {
    if (item.role && !textByRole[item.role]) {
      textByRole[item.role] = item;
    }
  }

  // Headline (baseline at y = -1.75)
  const headlineItem = textByRole.headline || textItems.find(i => String(i.text).includes('Light'));
  if (headlineItem) {
    const headlineObj = ctx.fontAtlas.createText(String(headlineItem.text), {
      fontSize: 68,
      color: '#e8ecf2',
      align: 'center',
    });
    headlineObj.position.y = -1.75;
    headlineObj.position.z = 0.1;
    group.add(headlineObj);
  } else {
    const headlineObj = ctx.fontAtlas.createText('Light, machined.', {
      fontSize: 68,
      color: '#e8ecf2',
      align: 'center',
    });
    headlineObj.position.y = -1.75;
    headlineObj.position.z = 0.1;
    group.add(headlineObj);
  }

  // Caption (baseline at y = -2.25, 0.5 units below headline)
  const captionItem = textByRole.caption || textItems.find(i => String(i.text).includes('SAPPHIRE'));
  if (captionItem) {
    const captionObj = ctx.fontAtlas.createText(String(captionItem.text), {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: 1.44,
    });
    captionObj.position.y = -2.25;
    captionObj.position.z = 0.1;
    group.add(captionObj);
  } else {
    const captionObj = ctx.fontAtlas.createText('SAPPHIRE OVER DIAL / ZERO DISTORTION', {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: 1.44,
    });
    captionObj.position.y = -2.25;
    captionObj.position.z = 0.1;
    group.add(captionObj);
  }

  // 7. CINEMATIC PRIMITIVE: depth-rotate on hover
  let primitiveResult = null;
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name === 'depth-rotate') {
        primitiveResult = ctx.primitives['depth-rotate'](group, {
          maxDeg: prim.params?.maxDeg ?? 10,
        });
        break;
      }
    }
  }

  // 8. CLEANUP
  group.userData.cleanup = () => {
    prismGeometry.dispose();
    prismMaterial.dispose();
    coreGeometry.dispose();
    coreMaterial.dispose();
    causticGeometry.dispose();
    causticMaterial.dispose();

    if (primitiveResult?.cleanup) {
      primitiveResult.cleanup();
    }

    gsap.killTweensOf(group.rotation);
    gsap.killTweensOf(group.scale);
  };

  return group;
}

function createTriangularPrism(sideLength, length) {
  // Equilateral triangle cross-section
  const h = (Math.sqrt(3) / 2) * sideLength;
  const vertices = [];
  const indices = [];

  // Front triangle vertices (z = -length/2)
  const zFront = -length / 2;
  vertices.push(
    sideLength / 2, 0, zFront,       // 0: right
    -sideLength / 2, 0, zFront,      // 1: left
    0, h, zFront                      // 2: top
  );

  // Back triangle vertices (z = length/2)
  const zBack = length / 2;
  vertices.push(
    sideLength / 2, 0, zBack,        // 3: right
    -sideLength / 2, 0, zBack,       // 4: left
    0, h, zBack                       // 5: top
  );

  // Triangular faces
  indices.push(0, 2, 1);              // Front
  indices.push(3, 4, 5);              // Back

  // Rectangular side faces (as triangles)
  indices.push(0, 1, 3);              // Bottom 1
  indices.push(1, 4, 3);              // Bottom 2
  indices.push(0, 3, 5);              // Right 1
  indices.push(0, 5, 2);              // Right 2
  indices.push(1, 2, 5);              // Left 1
  indices.push(1, 5, 4);              // Left 2

  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new BufferAttribute(new Float32Array(vertices), 3));
  geometry.setIndex(new BufferAttribute(new Uint32Array(indices), 1));
  geometry.computeVertexNormals();

  return geometry;
}
